<script setup lang="ts">
import {
  ClearOutlined,
  DeleteOutlined,
  EditOutlined,
  PlusOutlined,
  ReloadOutlined,
  SearchOutlined,
} from '@ant-design/icons-vue';
import { useAccess } from '@vben/access';
import { message, Modal, type FormInstance } from 'ant-design-vue';
import { computed, onMounted, reactive, ref } from 'vue';

import {
  createProduct,
  deleteProduct,
  getProductList,
  updateProduct,
  type Product,
  type ProductPayload,
} from '#/api/kadmin/generated/product';

type TablePagination = { current?: number; pageSize?: number };

const { hasAccessByCodes } = useAccess();
const canCreate = computed(() => hasAccessByCodes(['system:product:create', '*']));
const canUpdate = computed(() => hasAccessByCodes(['system:product:update', '*']));
const canDelete = computed(() => hasAccessByCodes(['system:product:delete', '*']));

const loading = ref(false);
const errorText = ref('');
const items = ref<Product[]>([]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const filters = reactive<Record<string, string>>({
  name: '',
  sku: '',
  description: '',
  publishedAt: '',
});

const columns = [
  { title: 'Id', dataIndex: 'id', key: 'id', width: 160, ellipsis: true },
  { title: '商品名称', dataIndex: 'name', key: 'name', width: 160, ellipsis: true },
  { title: '商品编码', dataIndex: 'sku', key: 'sku', width: 160, ellipsis: true },
  { title: '销售价格', dataIndex: 'price', key: 'price', width: 160, ellipsis: true },
  { title: '库存数量', dataIndex: 'stock', key: 'stock', width: 160, ellipsis: true },
  { title: '是否上架', dataIndex: 'active', key: 'active', width: 160, ellipsis: true },
  { title: 'Description', dataIndex: 'description', key: 'description', width: 160, ellipsis: true },
  { title: 'Published At', dataIndex: 'publishedAt', key: 'publishedAt', width: 160, ellipsis: true },
  { title: 'Created At', dataIndex: 'createdAt', key: 'createdAt', width: 160, ellipsis: true },
  { title: 'Updated At', dataIndex: 'updatedAt', key: 'updatedAt', width: 160, ellipsis: true },
  { title: '操作', key: 'action', width: 120, fixed: 'right' },
];

const pagination = computed(() => ({
  current: page.value,
  pageSize: pageSize.value,
  pageSizeOptions: ['10', '20', '50', '100'],
  showSizeChanger: true,
  showTotal: (value: number) => `共 ${value} 条`,
  total: total.value,
}));

async function fetchList() {
  loading.value = true;
  errorText.value = '';
  try {
    const result = await getProductList({
      page: page.value,
      pageSize: pageSize.value,
      name: filters.name || undefined,
      sku: filters.sku || undefined,
      description: filters.description || undefined,
      publishedAt: filters.publishedAt || undefined,
    });
    items.value = result.items;
    total.value = result.total;
  } catch (error) {
    errorText.value = error instanceof Error ? error.message : '加载失败';
  } finally {
    loading.value = false;
  }
}

function search() {
  page.value = 1;
  void fetchList();
}

function resetSearch() {
  filters.name = '';
  filters.sku = '';
  filters.description = '';
  filters.publishedAt = '';
  search();
}

function handleTableChange(paginationValue: TablePagination) {
  page.value = paginationValue.current ?? 1;
  pageSize.value = paginationValue.pageSize ?? 20;
  void fetchList();
}

const modalOpen = ref(false);
const submitting = ref(false);
const editingId = ref<null | number>(null);
const formRef = ref<FormInstance>();
const dirty = ref(false);

const formState = reactive<Record<string, any>>({
  name: '',
  sku: '',
  price: undefined,
  stock: undefined,
  active: false,
  description: '',
  publishedAt: '',
});

const rules: Record<string, unknown> = {
  name: [{ required: true, message: '请输入商品名称', trigger: 'blur' }],
  sku: [{ required: true, message: '请输入商品编码', trigger: 'blur' }],
};

function openCreate() {
  editingId.value = null;
  dirty.value = false;
  formState.name = '';
  formState.sku = '';
  formState.price = undefined;
  formState.stock = undefined;
  formState.active = false;
  formState.description = '';
  formState.publishedAt = '';
  modalOpen.value = true;
}

async function openEdit(record: Product) {
  editingId.value = record.id;
  dirty.value = false;
  formState.name = record.name;
  formState.sku = record.sku;
  formState.price = record.price;
  formState.stock = record.stock;
  formState.active = record.active;
  formState.description = record.description;
  formState.publishedAt = record.publishedAt;
  modalOpen.value = true;
}

function requestClose() {
  if (!dirty.value) {
    modalOpen.value = false;
    return;
  }
  Modal.confirm({
    title: '放弃修改？',
    content: '当前表单有未保存的修改。',
    okText: '放弃',
    okType: 'danger',
    cancelText: '继续编辑',
    onOk: () => {
      dirty.value = false;
      modalOpen.value = false;
    },
  });
}

function markDirty() {
  if (modalOpen.value) {
    dirty.value = true;
  }
}

async function submit() {
  try {
    await formRef.value?.validate();
  } catch {
    return;
  }
  submitting.value = true;
  try {
    const payload = {
      name: formState.name,
      sku: formState.sku,
      price: formState.price,
      stock: formState.stock,
      active: formState.active,
      description: formState.description,
      publishedAt: formState.publishedAt,
    } as ProductPayload;
    if (editingId.value === null) {
      await createProduct(payload);
      message.success('新增成功');
    } else {
      await updateProduct(editingId.value, payload);
      message.success('修改成功');
    }
    modalOpen.value = false;
    dirty.value = false;
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '提交失败');
  } finally {
    submitting.value = false;
  }
}

async function remove(record: Product) {
  try {
    await deleteProduct(record.id);
    message.success('删除成功');
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '删除失败');
  }
}

onMounted(() => {
  void fetchList();
});
</script>
